const d = $input.first().json.body;

// Determine survival tier
const score = parseFloat(d.survivalScore) || 0;
let tier = 'Critical';
let tierColor = '#dc2626';
if (score >= 75) { tier = 'Healthy'; tierColor = '#16a34a'; }
else if (score >= 50) { tier = 'Marginal'; tierColor = '#f59e0b'; }
else if (score >= 25) { tier = 'Danger'; tierColor = '#ea580c'; }

const projectedMembers = parseInt(d.projectedMembers) || 0;
const openingMRR = parseFloat(d.openingMRR) || 0;
const opexCoverage = parseFloat(d.opexCoverage) || 0;
const recoveryMembers = parseInt(d.recoveryMembers) || 0;
const recoveryMRR = parseFloat(d.recoveryMRR) || 0;
const recoveryLTV = parseFloat(d.recoveryLTV) || 0;
const monthlyOpex = parseFloat(d.monthlyOpex) || 0;

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, Helvetica, sans-serif; margin: 0; padding: 0; color: #1e293b; }
  .container { max-width: 640px; margin: 0 auto; padding: 40px 32px; }
  .header { text-align: center; margin-bottom: 32px; }
  .header h1 { font-size: 22px; color: #0f172a; margin: 0 0 4px; }
  .header p { font-size: 13px; color: #64748b; margin: 0; }
  .section { margin-bottom: 24px; }
  .section h2 { font-size: 15px; color: #334155; border-bottom: 2px solid #e2e8f0; padding-bottom: 6px; margin: 0 0 12px; }
  .row { display: flex; justify-content: space-between; padding: 6px 0; font-size: 14px; }
  .row .label { color: #64748b; }
  .row .value { font-weight: 600; color: #0f172a; }
  .tier-badge { display: inline-block; padding: 6px 18px; border-radius: 20px; color: #fff; font-weight: 700; font-size: 16px; background: ${tierColor}; }
  .tier-box { text-align: center; margin: 16px 0; }
  .bar-track { background: #e2e8f0; border-radius: 6px; height: 14px; margin-top: 4px; }
  .bar-fill { height: 14px; border-radius: 6px; }
  .cta { text-align: center; margin-top: 32px; padding: 20px; background: #f8fafc; border-radius: 8px; }
  .cta p { margin: 0; font-size: 14px; color: #334155; }
</style>
</head>
<body>
<div class="container">

  <div class="header">
    <h1>Presale Survival Test Results</h1>
    <p>Prepared for ${d.name || 'N/A'} &mdash; ${d.role || 'N/A'} at ${d.brandName || 'N/A'}</p>
  </div>

  <div class="section">
    <h2>Contact Details</h2>
    <div class="row"><span class="label">Email</span><span class="value">${d.email || 'N/A'}</span></div>
    <div class="row"><span class="label">Phone</span><span class="value">${d.phone || 'N/A'}</span></div>
    <div class="row"><span class="label">LinkedIn</span><span class="value">${d.linkedin || 'N/A'}</span></div>
  </div>

  <div class="section">
    <h2>Business Profile</h2>
    <div class="row"><span class="label">Unit Count</span><span class="value">${d.unitCount || 'N/A'}</span></div>
    <div class="row"><span class="label">Ad Spend</span><span class="value">$${parseFloat(d.adSpend || 0).toLocaleString()}</span></div>
    <div class="row"><span class="label">Population Density</span><span class="value">${d.populationDensity || 'N/A'}</span></div>
    <div class="row"><span class="label">B2B Leads</span><span class="value">${d.b2bLeads || 'N/A'}</span></div>
    <div class="row"><span class="label">Close Rate</span><span class="value">${d.closeRate || 'N/A'}%</span></div>
    <div class="row"><span class="label">Membership Value</span><span class="value">$${parseFloat(d.membershipValue || 0).toLocaleString()}</span></div>
    <div class="row"><span class="label">Member Lifetime</span><span class="value">${d.memberLifetime || 'N/A'} months</span></div>
    <div class="row"><span class="label">Monthly OPEX</span><span class="value">$${monthlyOpex.toLocaleString()}</span></div>
  </div>

  <div class="section">
    <h2>Survival Score</h2>
    <div class="tier-box"><span class="tier-badge">${score}/100 &mdash; ${tier}</span></div>
    <div class="bar-track"><div class="bar-fill" style="width:${score}%; background:${tierColor};"></div></div>
  </div>

  <div class="section">
    <h2>Key Metrics</h2>
    <div class="row"><span class="label">Projected Members</span><span class="value">${projectedMembers} / 200 target</span></div>
    <div class="row"><span class="label">Opening MRR</span><span class="value">$${openingMRR.toLocaleString()} / $30,000 threshold</span></div>
    <div class="row"><span class="label">OPEX Coverage</span><span class="value">${opexCoverage}%</span></div>
    <div class="row"><span class="label">MRR vs Threshold</span><span class="value">${d.mrrVsThreshold || 'N/A'}</span></div>
    <div class="row"><span class="label">Cash Position</span><span class="value">${d.cashPosition || 'N/A'}</span></div>
  </div>

  <div class="section">
    <h2>Revenue Recovery Potential</h2>
    <div class="row"><span class="label">Recovery Members</span><span class="value">${recoveryMembers}</span></div>
    <div class="row"><span class="label">Recovery MRR</span><span class="value">$${recoveryMRR.toLocaleString()}</span></div>
    <div class="row"><span class="label">Recovery LTV</span><span class="value">$${recoveryLTV.toLocaleString()}</span></div>
  </div>

  <div class="cta">
    <p><strong>Booked a call with Revryze to review your results.</strong></p>
  </div>

</div>
</body>
</html>`;

return [{
  json: {
    html,
    email: d.email,
    name: d.name,
    brandName: d.brandName
  }
}];
